// Read-only diagnostic: compares each Sequelize model's defined attributes
// against the live Postgres information_schema.columns. Does NOT sync/alter.
const path = require('path');
process.chdir(path.join(__dirname, '..', '..', '..', '..', '..', '..', '..')); // no-op fallback
const serverDir = 'C:\\Fullstack Assignment (FlowGuard)\\FlowGuard\\server';
process.chdir(serverDir);

const db = require(path.join(serverDir, 'models'));

async function main() {
  const modelNames = Object.keys(db).filter(k => k !== 'sequelize' && k !== 'Sequelize');
  const qi = db.sequelize.getQueryInterface();

  let anyMissing = false;

  for (const name of modelNames) {
    const model = db[name];
    const tableName = typeof model.getTableName === 'function' ? model.getTableName() : model.tableName;
    const tableNameStr = typeof tableName === 'object' ? tableName.tableName : tableName;

    let liveDesc;
    try {
      liveDesc = await qi.describeTable(tableNameStr);
    } catch (err) {
      console.log(`\n[TABLE MISSING] ${name} -> "${tableNameStr}": ${err.message}`);
      anyMissing = true;
      continue;
    }

    const liveCols = new Set(Object.keys(liveDesc));
    const modelAttrs = model.rawAttributes || model.tableAttributes;
    const missingCols = [];

    for (const [attrName, attrDef] of Object.entries(modelAttrs)) {
      const colName = attrDef.field || attrName;
      if (!liveCols.has(colName)) {
        missingCols.push(colName);
      }
    }

    if (missingCols.length > 0) {
      console.log(`\n[MISSING COLUMNS] ${name} (table "${tableNameStr}"):`);
      missingCols.forEach(c => console.log(`   - ${c}`));
      anyMissing = true;
    }
  }

  if (!anyMissing) {
    console.log('\nNo missing tables or columns detected. Live DB matches all models.');
  }

  await db.sequelize.close();
}

main().catch(async (err) => {
  console.error('Diagnostic failed:', err.message);
  try { await db.sequelize.close(); } catch (e) {}
  process.exit(1);
});

