module.exports = (sequelize, DataTypes) => {
    const User = sequelize.define("User", {
        name: {
            type: DataTypes.STRING(100),
            allowNull: false
        },
        email: {
            type: DataTypes.STRING(100),
            allowNull: false,
            unique: true
        },
        password: {
            type: DataTypes.STRING(100),
            allowNull: false
        },
        role: {
            type: DataTypes.ENUM('FM', 'Tenant', 'Staff'), 
            defaultValue: 'Tenant'
        },
        // --- HYBRID REGISTRATION CODE LOGIC ---
        companyCode: {
            type: DataTypes.STRING(50), 
            allowNull: true,
            unique: true // One active code per Tenant
        },
        codeCreatedAt: {
            type: DataTypes.DATE,
            allowNull: true // Tracks the 48-hour expiration clock
        },
        codeMaxUsage: {
            type: DataTypes.INTEGER,
            defaultValue: 10,
            allowNull: false // Max "punches" on the card
        },
        codeCurrentUsage: {
            type: DataTypes.INTEGER,
            defaultValue: 0,
            allowNull: false // Current count of registrations
        },
        // ---------------------------------------
        managerId: {
            type: DataTypes.INTEGER,
            allowNull: true
        },
        // --- BIOMETRIC SECURITY LOGIC ---
        isEnrolled: {
            type: DataTypes.BOOLEAN,
            defaultValue: false, // Forces new users to the enrollment screen
            allowNull: false
        },
        faceVector: {
            type: DataTypes.ARRAY(DataTypes.FLOAT),
            allowNull: true
        },
        // ---------------------------------------
        isActive: {
            type: DataTypes.BOOLEAN,
            defaultValue: true,
            allowNull: false
        },
        // --- SESSION REVOCATION ---
        // Stamped into every JWT at login and compared on every authenticated
        // request. Incremented on password change/reset and on suspension so
        // all previously issued tokens (e.g. on a lost device) die instantly.
        tokenVersion: {
            type: DataTypes.INTEGER,
            defaultValue: 0,
            allowNull: false
        },
        // --- FORGOT/RESET PASSWORD ---
        // Only the SHA-256 hash of the emailed reset token is stored — never
        // the raw token. Cleared as soon as the reset completes.
        passwordResetTokenHash: {
            type: DataTypes.STRING(64),
            allowNull: true
        },
        passwordResetExpiresAt: {
            type: DataTypes.DATE,
            allowNull: true
        }
    }, {
        tableName: 'users',
        paranoid: false // Hard deletes as requested earlier
    });

    User.associate = (models) => {
        User.belongsTo(models.User, {
            as: 'Manager',
            foreignKey: 'managerId'
        });

        User.hasMany(models.User, {
            as: 'StaffMembers',
            foreignKey: 'managerId'
        });

        User.hasMany(models.Attendance, {
            foreignKey: 'userId',
            as: 'Attendances'
        });

        User.hasOne(models.EvaluationParticipant, {
            foreignKey: 'userId',
            as: 'EvaluationParticipant',
            onDelete: 'SET NULL'
        });
    };

    return User;
};

module.exports = (sequelize, DataTypes) => {
    const MonitoringZone = sequelize.define("MonitoringZone", {
        zone_name: {
            type: DataTypes.STRING(255),
            allowNull: false
        },
        location: {
            type: DataTypes.STRING(255),
            allowNull: false
        },
        // Legacy unattended-object threshold, in MINUTES. Read directly (raw SQL) by
        // ai-service/main.py::_refresh_zone_info, which falls back to time_threshold * 60
        // seconds whenever unattended_threshold_seconds (below) is not set. Kept as-is so
        // existing rows/behaviour are never silently reinterpreted.
        time_threshold: {
            type: DataTypes.INTEGER,
            allowNull: false
        },
        // Detection Setup fields (additive) ---------------------------------------------
        monitored_classes: {
            type: DataTypes.TEXT,
            allowNull: false,
            defaultValue: '[]'
        },
        density_threshold: {
            type: DataTypes.INTEGER,
            allowNull: true
        },
        // Unattended-object threshold in SECONDS, set from the Detection Setup page.
        // Takes precedence over the legacy time_threshold (minutes) when present — see
        // ai-service/main.py::_refresh_zone_info.
        unattended_threshold_seconds: {
            type: DataTypes.INTEGER,
            allowNull: true
        },
        alert_cooldown_seconds: {
            type: DataTypes.INTEGER,
            allowNull: true
        },
        severity: {
            type: DataTypes.ENUM('Low', 'Medium', 'High', 'Critical'),
            allowNull: false,
            defaultValue: 'Medium'
        },
        // Free-text soft link into the (localStorage-only) response-team directory —
        // not a foreign key, matching the SecurityLog.personnelName soft-link convention.
        assigned_team: {
            type: DataTypes.STRING(255),
            allowNull: true
        },
        detection_enabled: {
            type: DataTypes.BOOLEAN,
            allowNull: false,
            defaultValue: true
        },
        // Explicit Detection Setup category, set by the FM instead of being guessed back
        // from severity/density/monitored_classes after reload. Nullable so rows created
        // before this field existed keep loading — serializeZone() below fills in the
        // 'unattended_object' fallback for those.
        detection_type: {
            type: DataTypes.STRING(30),
            allowNull: true
        }
    }, {
        tableName: 'monitoring_zones',
        paranoid: true
    });

    MonitoringZone.associate = (models) => {
        MonitoringZone.hasMany(models.Camera, { foreignKey: 'zone_id', as: 'cameras' });
    };

    return MonitoringZone;
};

module.exports = (sequelize, DataTypes) => {
  const SecurityLog = sequelize.define('SecurityLog', {
    id: { type: DataTypes.STRING, primaryKey: true, allowNull: false },
    time: { type: DataTypes.STRING, allowNull: false },
    type: { type: DataTypes.STRING, allowNull: false },
    desc: { type: DataTypes.TEXT, allowNull: false },
    severity: { type: DataTypes.STRING, allowNull: false, defaultValue: 'safe' },
    icon: { type: DataTypes.STRING, allowNull: false },

    // 🎯 Dedicated column to link to the Personnel Page
    personnelName: {
      type: DataTypes.STRING,
      allowNull: true, // True because intruders won't have a registered name
      description: 'The exact name of the verified staff member'
    },

    // --- AUTOMATIC RECOGNITION AUDIT FIELDS (additive, all nullable) ---
    // Populated by the Node facial-recognition route. Audit metadata only —
    // never a snapshot and never biometric template data.
    matchedUserId: {
      type: DataTypes.INTEGER,
      allowNull: true // The unique User ID the recognition matched, when known
    },
    confidence: {
      type: DataTypes.FLOAT,
      allowNull: true // Recognition confidence at the time of the event
    },
    cameraLocation: {
      type: DataTypes.STRING,
      allowNull: true // Which gate/camera produced the event
    },

    // --- MANUAL FM REVIEW WORKFLOW ---
    // FM staff triage suspicious/critical events through these fields.
    reviewStatus: {
      type: DataTypes.STRING,
      allowNull: false,
      defaultValue: 'Pending Review' // Pending Review | False Positive | Escalated | Resolved
    },
    reviewNotes: {
      type: DataTypes.TEXT,
      allowNull: true // FM's manual resolution notes
    },
    reviewedBy: {
      type: DataTypes.STRING,
      allowNull: true // Name/email of the FM who actioned the log
    },
    reviewedAt: {
      type: DataTypes.DATE,
      allowNull: true
    }
  }, {
    tableName: 'security_logs',
    timestamps: true, 
  });

  return SecurityLog;
};

